// Üretilen dosya: tool/ozgun/uret.py. Fizik · Elektrik devreleri ve elektrik enerjisi hesapları (zor).
const ozPhysics11Zor = <(String, String, List<String>, String)>[
  ('Bir elektrolit çözeltide her saniye 3 × 10¹⁸ Na⁺ iyonu bir yönde, 3 × 10¹⁸ Cl⁻ iyonu ters yönde geçmektedir. Çözeltideki akım yaklaşık kaç amperdir? (e = 1,6 × 10⁻¹⁹ C)', '0,96 A', ['0,48 A', '1,92 A', '0,096 A'], 'Zıt yönlü hareket eden zıt işaretli yükler akıma aynı yönde katkı verir. Toplam yük akışı 6×10¹⁸ × 1,6×10⁻¹⁹ = 0,96 C/s\'dir.'),
  ('Kesit alanı 2 mm² olan bir bakır telden 10 A akım geçiyor. Bakırda serbest elektron yoğunluğu 8,5 × 10²⁸ m⁻³ ise sürüklenme hızı yaklaşık kaç mm/s\'dir? (e = 1,6 × 10⁻¹⁹ C)', '0,37 mm/s', ['3,7 mm/s', '37 mm/s', '0,037 mm/s'], 'v = I/(nAe) = 10 / (8,5×10²⁸ × 2×10⁻⁶ × 1,6×10⁻¹⁹) ≈ 3,7×10⁻⁴ m/s = 0,37 mm/s\'dir.'),
  ('Bir metal tel eritilip hacmi korunarak uzunluğu üç katına çıkacak biçimde çekiliyor. Yeni direnç ilk direncin kaç katıdır?', '9 katı', ['3 katı', '6 katı', '1/3 katı'], 'Hacim sabit olduğundan uzunluk 3 katına çıkınca alan üçte bire iner. R = ρL/A olduğundan direnç 3 × 3 = 9 katına çıkar.'),
  ('Hacmi sabit tutularak bir telin uzunluğu %10 artırılıyor. Telin direnci yaklaşık yüzde kaç artar?', '%21', ['%10', '%20', '%100'], 'Uzunluk 1,1 katına çıkınca alan 1/1,1 katına iner. Direnç 1,1 × 1,1 = 1,21 katına yani %21 artar.'),
  ('Boyutları 1 cm × 2 cm × 4 cm olan dikdörtgen prizma biçimli bir iletken blokta akım en uzun kenar boyunca, sonra en kısa kenar boyunca geçirilirse iki durumdaki dirençlerin oranı R(uzun)/R(kısa) kaç olur?', '16', ['4', '8', '1/16'], 'Uzun yönde L = 4, A = 2 (1×2); kısa yönde L = 1, A = 8 (2×4). Oran (4/2) / (1/8) = 16\'dır.'),
  ('Bir telin direncinin birimi olan ohm, SI temel birimleriyle hangi ifadeye eşittir?', 'kg·m²·s⁻³·A⁻²', ['kg·m²·s⁻²·A⁻¹', 'kg·m²·s⁻³·A⁻²·K⁻¹', 'kg·m²·s⁻³·A⁻¹'], 'Ω = V/A ve V = W/A = kg·m²·s⁻³·A⁻¹ olduğundan Ω = kg·m²·s⁻³·A⁻² bulunur.'),
  ('Pilin eksi ucu toprağa bağlıdır (potansiyeli 0). Eksi uca 4 Ω, onun ardından artı uca 6 Ω\'luk direnç seri bağlıdır ve pil 20 V verir. İki direncin ortak noktasının potansiyeli kaç volttur?', '8 V', ['12 V', '10 V', '4 V'], 'Akım I = 20/10 = 2 A\'dir. Toprağa bağlı uçtan itibaren 4 Ω üzerinde 2 × 4 = 8 V düşer; ortak noktanın potansiyeli 8 V\'tur.'),
  ('24 V\'luk kaynağa 8 Ω\'luk bir direnç, birbirine paralel 12 Ω ve 6 Ω\'luk dirençlerle seri bağlanmıştır. 12 Ω\'luk dirençten geçen akım kaç amperdir?', '2/3 A', ['2 A', '16/3 A', '1/3 A'], 'Paralel grup 4 Ω\'dur; toplam 12 Ω, ana akım 2 A. Gruptaki gerilim 2 × 4 = 8 V\'tur. 12 Ω\'dan geçen akım 8/12 = 2/3 A\'dir.'),
  ('12 kenarının her birinin direnci R olan bir küp iskeletinde, küpün cisim köşegeninin iki ucu arasındaki eşdeğer direnç kaç R\'dir?', '5R/6', ['R/2', '3R/4', '7R/12'], 'Simetri nedeniyle köşeden çıkan üç kol eşit akım taşır, ardından 6 kenar ve son 3 kenar gelir: R/3 + R/6 + R/3 = 5R/6 olur.'),
  ('Her adımında 1 Ω\'luk seri ve 1 Ω\'luk paralel direnç bulunan sonsuz uzunlukta bir merdiven devresinin başlangıç uçları arasındaki eşdeğer direnç kaç ohmdur?', '(1+√5)/2 ≈ 1,62 Ω', ['(3+√5)/2 ≈ 2,618 Ω', '1,5 Ω', '(√5−1)/2 ≈ 0,62 Ω'], 'Eşdeğer direnç x ise x = 1 + (x·1)/(x+1) olur; buradan x² − x − 1 = 0 ve x = (1+√5)/2 ≈ 1,62 Ω bulunur.'),
  ('Dengede olan bir Wheatstone köprüsünün ortadaki köprü koluna konulan 100 Ω\'luk direnç, ideal bir iletken telle değiştirilirse devrenin eşdeğer direnci nasıl değişir?', 'Değişmez, çünkü köprü kolundan akım geçmiyordu', ['Sıfıra düşer, çünkü devre kısa devre olur', 'Yarıya iner, çünkü iki kol birleşir', 'Sonsuza çıkar, çünkü köprü kolu kısa devre olur'], 'Dengede köprü uçları eşpotansiyeldir; aralarındaki eleman değişse de bu uçlar arasından akım geçmez ve eşdeğer direnç aynı kalır.'),
  ('Emk\'sı 12 V, iç direnci 2 Ω olan bir üretece 1 Ω\'luk dış direnç bağlandığında harcanan güç ile aynı gücün harcandığı diğer dış direnç değeri kaç ohmdur?', '4 Ω', ['2 Ω', '3 Ω', '0,25 Ω'], 'R₁R₂ = r² olduğunda iki dirençte harcanan güç eşittir: R₂ = 4/1 = 4 Ω. Gerçekten de iki durumda da güç 16 W\'tır.'),
  ('Her biri 3 V emk\'lı ve 1 Ω iç dirençli iki pil seri bağlanarak oluşturulan iki özdeş grup birbirine paralel bağlanıp 2 Ω\'luk dirence bağlanıyor. Dirençten geçen akım kaç amperdir?', '2 A', ['3 A', '1 A', '1,5 A'], 'Her grup 6 V ve 2 Ω\'dur; paralel bağlanınca 6 V ve 1 Ω olur. I = 6/(2+1) = 2 A\'dir.'),
  ('Bir üreteç 2 Ω\'luk dirence bağlandığında 3 A, 5 Ω\'luk dirence bağlandığında 1,5 A akım veriyor. Üretecin emk\'sı kaç volttur?', '9 V', ['6 V', '12 V', '7,5 V'], 'ε = 3(2 + r) = 1,5(5 + r) denkleminden 6 + 3r = 7,5 + 1,5r olur; r = 1 Ω ve ε = 3 × 3 = 9 V bulunur.'),
  ('Emk\'sı 10 V ve 5 V olan iki ideal pil, 1 Ω\'luk birer dirençle ayrı kollarda bağlıdır; kollar bir yanda doğrudan birleşir ve diğer yanda ortak bir 2 Ω\'luk yük direncine bağlanır (iki pil de yük akımını aynı yönde beslemeye çalışacak biçimde). Yük direncinden geçen akım kaç amperdir?', '3 A', ['5 A', '6 A', '2,5 A'], 'Düğüm gerilimi V ise (10−V)/1 + (5−V)/1 = V/2 olur; V = 6 V bulunur. Yük akımı 6/2 = 3 A\'dir.'),
  ('10 V ve 5 V\'luk ideal piller 1 Ω\'luk birer dirençle ayrı kollarda bağlıdır ve ortak 2 Ω\'luk yüke bağlıdır. Yük uçlarındaki düğüm gerilimi 6 V\'tur. 5 V\'luk pil için ne söylenebilir?', 'Akım pilin içinden ters yönde geçer, pil şarj olur', ['Pil normal biçimde enerji verir ve akım artı uçtan çıkar', 'Pilden hiç akım geçmez', 'Pil kısa devre olur ve yanar'], '5 V\'luk koldan (5−6)/1 = −1 A akım geçer; akım pilin artı ucuna girer, yani pil enerji vermek yerine şarj olur.'),
  ('Emk\'sı 9 V, iç direnci 1 Ω olan bir pil ile emk\'sı 6 V, iç direnci 2 Ω olan bir pil, aynı kutuplar birbirine gelecek biçimde paralel bağlanmış ve dış devreye bağlanmamıştır. Pillerin oluşturduğu halkadan geçen akım kaç amperdir?', '1 A', ['5 A', '3 A', '0,5 A'], 'Halkada emklerin farkı etkindir: (9 − 6)/(1 + 2) = 1 A\'dir. Bu yüzden farklı emkli piller paralel bağlanmamalıdır.'),
  ('Emk\'sı 10 V olan ideal bir kaynağa seri bağlı 100 kΩ\'luk iki direncin ikincisine, iç direnci 100 kΩ olan bir voltmetre paralel bağlanıyor. Voltmetre yaklaşık kaç volt gösterir?', '3,33 V', ['5 V', '2,5 V', '2,857 V'], 'Voltmetre ve direnç paralel 50 kΩ eşdeğer verir. Gerilim bölünmesiyle V = 10 × 50/(50+100) = 3,33 V olur; ölçüm gerçek 5 V\'tan sapar.'),
  ('Tam ölçek akımı 1 mA, iç direnci 50 Ω olan bir galvanometre 0–1 A\'lik ampermetreye dönüştürülmek isteniyor. Galvanometreye paralel bağlanacak şönt direnç yaklaşık kaç ohm olmalıdır?', '0,05 Ω', ['50 Ω', '0,5 Ω', '0,005 Ω'], 'Galvanometre gerilimi 0,001 × 50 = 0,05 V\'tur. Şönttten 0,999 A geçeceğinden R ≈ 0,05/0,999 ≈ 0,05 Ω olur.'),
  ('220 V için 100 W ve 25 W yazan iki lamba seri bağlanıp 220 V\'a takılıyor. 100 W\'lık lambanın uçlarındaki gerilim kaç volttur?', '44 V', ['176 V', '110 V', '220 V'], 'Dirençler 484 Ω ve 1936 Ω\'dur. Gerilim dirençle orantılı bölünür: 220 × 484/2420 = 44 V\'tur.'),
  ('220 V için 100 W ve 25 W yazan iki lamba seri bağlanıp 220 V\'a takıldığında devreden çekilen toplam güç kaç watttır?', '20 W', ['125 W', '80 W', '50 W'], 'Toplam direnç 484 + 1936 = 2420 Ω\'dur. P = V²/R = 220²/2420 = 20 W\'tır.'),
  ('Özdeş üç lamba seri bağlıdır. Lambalardan biri kısa devre edilirse kalan iki lambanın her birinin gücü ilk durumun kaç katına çıkar? (Kaynak gerilimi sabit)', '9/4 katına', ['3/2 katına', '2 katına', '27/8 katına'], 'Başta her lambada V/3 vardı; sonra V/2 olur. P ∝ V² olduğundan güç (1/2)²/(1/3)² = 9/4 katına çıkar.'),
  ('Bir devrede L₁ lambası, birbirine paralel L₂ ve L₃ lambalarıyla seri bağlıdır. L₃\'ün koluna konulan S anahtarı kapatılırsa L₁ ve L₂\'nin parlaklığı nasıl değişir? (Lambalar özdeş, kaynak ideal)', 'L₁ daha parlak, L₂ daha sönük olur', ['Her ikisi de daha parlak olur ve toplam akım azalır', 'L₁ daha sönük, L₂ daha parlak olur', 'Her ikisi de değişmez'], 'S kapanınca toplam direnç azalır, L₁\'den geçen akım artar. Seri gruptaki gerilim bölümü L₁ lehine değiştiği için L₂\'nin gerilimi ve parlaklığı azalır.'),
  ('Eski tip bir elektrik sayacının diski 1 kWh için 600 devir yapmaktadır. Yalnız bir cihaz çalışırken disk 12 dakikada 120 devir yapıyorsa cihazın gücü kaç watttır?', '1000 W', ['500 W', '10 000 W', '200 W'], '120 devir 0,2 kWh\'e karşılık gelir; bu enerji 12 dakikada (0,2 saat) harcandığından güç 0,2/0,2 = 1 kW = 1000 W\'tır.'),
  ('Verimi %80 olan 500 W\'lık bir daldırma ısıtıcı, 0,5 kg suyu 20 °C\'den 100 °C\'ye ısıtıyor. Gereken süre kaç saniyedir? (c = 4200 J/kg·°C)', '420 s', ['336 s', '525 s', '1680 s'], 'Suya aktarılan ısı 0,5 × 4200 × 80 = 168 000 J\'dür. Elektrik enerjisi 168 000/0,8 = 210 000 J\'dür; süre 210 000/500 = 420 s.'),
  ('10 V\'a yüklenmiş 6 μF\'lık kondansatör, yüksüz 3 μF\'lık bir kondansatöre paralel bağlandığında sistemin enerjisinde kaç μJ\'lük azalma olur?', '100 μJ', ['300 μJ', '200 μJ', '1000 μJ'], 'Başlangıç enerjisi ½·6·10² = 300 μJ; son enerji ½·9·(20/3)² = 200 μJ\'dir. Aradaki 100 μJ bağlantı sırasında ısı ve ışımaya gider.'),
  ('Bir üretece bağlı olmayan, yüklü paralel levhalı bir kondansatörün levhaları arasına dielektrik sabiti 3 olan bir yalıtkan tamamen yerleştiriliyor. Depolanan enerji nasıl değişir?', 'Üçte birine düşer', ['3 katına çıkar, çünkü sığa artar', 'Değişmez, çünkü yük sabittir', '9 katına çıkar'], 'Yük sabittir, sığa 3 katına çıkar. U = q²/(2C) olduğundan enerji üçte birine iner.'),
  ('Üreteçten ayrılmış, yüklü paralel levhalı bir kondansatörün levhaları arasındaki uzaklık iki katına çıkarılırsa levhalar arasındaki elektrik alan şiddeti nasıl değişir?', 'Değişmez', ['Yarıya iner', 'İki katına çıkar', 'Dört katına çıkar'], 'Yük ve levha alanı aynı kaldığından E = σ/ε₀ değişmez; potansiyel farkı ise uzaklıkla birlikte iki katına çıkar.'),
  ('12 V\'luk üretece 3 μF\'lık C₁ kondansatörü, birbirine paralel iki özdeş 6 μF\'lık kondansatörle seri bağlanmıştır. C₁\'in uçları arasındaki gerilim kaç volttur?', '9,6 V', ['4 V', '2,88 V', '12 V'], 'Paralel grup 12 μF\'tır; eşdeğer sığa (3·12)/(15) = 2,4 μF. Yük q = 2,4 × 12 = 28,8 μC\'tir ve V₁ = 28,8/3 = 9,6 V olur.'),
  ('Bir kondansatörün sığasının birimi olan farad, SI temel birimleriyle hangisine eşittir?', 'A²·s⁴·kg⁻¹·m⁻²', ['A·s²·kg⁻¹·m⁻²', 'A²·s⁴·kg⁻¹·m⁻²·K⁻¹', 'A·s·kg⁻¹·m⁻²'], 'F = C/V; C = A·s ve V = kg·m²·s⁻³·A⁻¹ olduğundan F = A²·s⁴·kg⁻¹·m⁻² bulunur.'),
  ('Ters yönde çalışan 5,1 V\'luk bir zener diyot, 690 Ω\'luk bir dirençle seri bağlanıp 12 V\'luk kaynağa takılıyor. Devreden geçen akım kaç miliamperdir?', '10 mA', ['17,4 mA', '7,4 mA', '1 mA'], 'Zener diyot uçlarında 5,1 V\'u sabit tutar; dirençte 6,9 V düşer. I = 6,9/690 = 10 mA olur.'),
  ('10 MW\'lık güç 100 kV\'ta, toplam direnci 2 Ω olan bir hat üzerinden taşınıyor. Hat kaybı iletilen gücün yüzde kaçıdır?', '%0,2', ['%2', '%0,02', '%20'], 'Akım I = 10⁷/10⁵ = 100 A; kayıp I²R = 10⁴ × 2 = 20 kW. 20 kW / 10 MW = 0,002 yani %0,2\'dir.'),
  ('9 V\'a bağlı 10 kΩ\'luk potansiyometrenin sürgüsü ortadadır. Çıkışa 10 kΩ\'luk bir yük bağlanırsa çıkış gerilimi yaklaşık kaç volt olur?', '3,6 V', ['4,5 V', '3 V', '3,33 V'], 'Alt yarı (5 kΩ) ile yük (10 kΩ) paralel olup 3,33 kΩ\'dur. Bölümleyici: 9 × 3,33/(3,33 + 5) = 3,6 V.'),
  ('Bir ısı pompası 1 kWh elektrik enerjisi harcayıp ortama 3 kWh ısı veriyor. Bu durum enerjinin korunumuna neden aykırı değildir?', 'Fazla ısı ortamdan çekilir; ısı pompası enerji üretmez, taşır', ['Elektrik enerjisi ısı pompasının içinde üç katına çıkarak ısıya dönüşür', 'Enerji korunumu ısı için geçerli değildir', 'Isı pompası soğuk ortamda enerji yaratır'], 'Isı pompası düşük sıcaklıktaki ortamdan ısı alıp yüksek sıcaklıktaki ortama aktarır. Verilen 3 kWh = 1 kWh elektrik + ortamdan çekilen 2 kWh\'tir.'),
  ('10 000 mAh (3,7 V) bir güç bankası, 3000 mAh (3,7 V) bataryalı bir telefonu şarj etmektedir. Dönüşüm verimi %80 ise güç bankası telefonu kaç kez tam şarj edebilir?', '2 kez', ['3,33 kez', '4 kez', '0,8 kez'], 'Güç bankası 37 Wh, telefon 11,1 Wh depolar. Verimle 37 × 0,8 = 29,6 Wh kullanılabilir; 29,6/11,1 ≈ 2,67 olduğundan tam 2 şarj yapılır.'),
  ('2019\'da yürürlüğe giren SI birimleri revizyonunda amper hangi sabit değere bağlı olarak tanımlanmıştır?', 'Temel yük e\'nin sabit bir sayısal değerine', ['Işık hızı c\'nin ve Planck sabiti h\'nin birlikte alınan değerine', 'Planck sabiti h\'ye', 'Boltzmann sabiti k\'ya'], '2019 revizyonunda elektron yükü e\'nin değeri tam olarak 1,602176634 × 10⁻¹⁹ C kabul edilmiş ve amper buna dayanarak tanımlanmıştır.'),
  ('Wheatstone köprüsü devresini ilk kez 1833\'te icat eden, ancak Wheatstone\'un 1843\'te yaygınlaştırdığı düzeneğin mucidi kimdir?', 'Samuel Hunter Christie', ['Gustav Kirchhoff', 'Charles Augustin de Coulomb', 'William Thomson'], 'Köprü devresini ilk bulan Samuel Hunter Christie\'dir; Charles Wheatstone onu 1843\'te tanıtıp geliştirdiği için devre onun adıyla anılır.'),
  ('Seri bağlı iki lambadan birinin teli kopmuştur. Voltmetre kopuk lambanın uçlarına bağlanırsa neyi gösterir ve diğer lambaya ne olur?', 'Yaklaşık kaynak gerilimini gösterir; diğer lamba yanmaz', ['Sıfırı gösterir; diğer lamba parlak yanar', 'Kaynak geriliminin yarısını gösterir; diğer lamba yarı parlak yanar', 'Sıfırı gösterir; diğer lamba normal yanar'], 'Kopuk lamba devreyi açar, akım sıfırdır. Voltmetrenin çok büyük direnci nedeniyle gerilimin hemen hemen tamamı bu uçlarda ölçülür; diğer lamba söner.'),
  ('Özdeş A, B, C lambalarında B ile C paralel, bu grup A ile seri bağlıdır. B lambasının teli koparsa A ve C lambalarının parlaklığı nasıl değişir?', 'A sönükleşir, C parlaklaşır', ['A parlaklaşır, C sönükleşir', 'İkisi de parlaklaşır, çünkü toplam direnç azalır', 'İkisi de değişmez'], 'Başta A\'dan 2V/3R, C\'den V/3R geçer. B kopunca A ile C seri kalır ve ikisinden de V/2R geçer: A\'nın akımı azalır, C\'nin akımı artar.'),
  ('Ampermetre ile voltmetre bağlama hatası sonucu bir öğrenci voltmetreyi dirençle seri, ampermetreyi ise paralel bağlıyor. Ampermetrenin okuması neden beklenenden çok farklı olur?', 'Seri voltmetre akımı çok küçültür, paralel ampermetre direnci kısa devre eder', ['Ampermetre gerilim ölçtüğü için', 'Voltmetre devredeki akımı iki katına çıkarır ve ampermetre bunu tamamen doğru ölçemez', 'Direnç ampermetre içinde erir'], 'Seri voltmetre toplam direnci çok büyütür; paralel ampermetre direncin uçlarını kısa devre eder. Ölçülen değer devrenin gerçek akımını yansıtmaz.'),
  ('İki direncin seri eşdeğeri 10 Ω, paralel eşdeğeri 2,4 Ω\'dur. Bu dirençlerden büyük olanı kaç ohmdur?', '6 Ω', ['4 Ω', '8 Ω', '5 Ω'], 'R₁ + R₂ = 10 ve R₁R₂/(R₁+R₂) = 2,4 olduğundan R₁R₂ = 24\'tür. x² − 10x + 24 = 0 denkleminden dirençler 4 Ω ve 6 Ω bulunur.'),
  ('Direnci R olan düzgün bir tel ortasından ikiye katlanarak iki ucu birbirine yapıştırılıyor (iki parça birbirine paralel). Katlanmış telin direnci kaç R olur?', 'R/4', ['R/2', '2R', 'R/8'], 'Katlanınca uzunluk yarıya inip kesit alanı iki katına çıkar. R = ρL/A olduğundan direnç 1/4\'üne iner: R/4.'),
  ('Bir kondansatör 10 V\'luk bir kaynaktan bir direnç üzerinden doldurulurken (C = 100 μF), dirençte ısıya dönüşen toplam enerji kaç milijouledir?', '5 mJ', ['10 mJ', '2,5 mJ', '0,5 mJ'], 'Kaynağın yaptığı iş CV² = 10 mJ\'dir. Kondansatörde ½CV² = 5 mJ depolanır, kalan 5 mJ direnç dahil kayıplarda ısıya dönüşür; bu değer direncin değerinden bağımsızdır.'),
  ('12 V\'luk bir kaynağa iki eşit 1 MΩ\'luk direnç seri bağlanmıştır. İç direnci 1 MΩ olan bir voltmetre, bir direncin uçlarına bağlanırsa kaç volt gösterir?', '4 V', ['6 V', '8 V', '3 V'], 'Voltmetre ile direnç paralel 0,5 MΩ eder. Gerilim bölünmesiyle V = 12 × 0,5/(0,5 + 1) = 4 V okunur; gerçek değer olan 6 V\'tan sapma voltmetrenin yüklemesinden kaynaklanır.'),
  ('Emk\'ları 10 V olan iki ideal olmayan pil paralel bağlanmıştır; iç dirençleri 1 Ω ve 2 Ω\'dur. Ortak uçlarına 2 Ω\'luk bir yük bağlanırsa yükten geçen akım kaç amperdir?', '3,75 A', ['5 A', '2,5 A', '1,875 A'], 'Düğüm gerilimi V ise (10−V)/1 + (10−V)/2 = V/2 olur; V = 7,5 V bulunur. Yük akımı 7,5/2 = 3,75 A\'dir.'),
  ('20 °C\'de 4,5 Ω olan tungsten flamanın direnç sıcaklık katsayısı 4,5 × 10⁻³ /°C\'dir (doğrusal kabul). Lamba yanarken direnç 45 Ω\'a çıkıyorsa flamanın sıcaklığı yaklaşık kaç °C artmıştır?', '2000 °C', ['200 °C', '500 °C', '20 000 °C'], 'R = R₀(1 + αΔT) için 45 = 4,5(1 + 4,5×10⁻³ΔT) olur; 1 + 4,5×10⁻³ΔT = 10 ve ΔT = 2000 °C bulunur.'),
  ('Özdirenci 1,1 × 10⁻⁶ Ω·m, kesit alanı 0,2 mm² olan nikel-krom telden 220 V\'ta 1000 W\'lık bir ısıtıcı yapılacaktır. Telin uzunluğu yaklaşık kaç metre olmalıdır?', '8,8 m', ['88 m', '0,88 m', '4,4 m'], 'Gereken direnç R = V²/P = 48,4 Ω\'dur. L = RA/ρ = 48,4 × 2×10⁻⁷ / 1,1×10⁻⁶ = 8,8 m bulunur.'),
  ('Otomatik sigortalarda (devre kesicilerde) aşırı yük ve kısa devre korumasını sağlayan mekanizmalar sırasıyla hangileridir?', 'Termik (bimetal) ve manyetik', ['Manyetik ve termik', 'İki mekanizma da bimetal', 'İki mekanizma da elektromıknatıs ve ısıdan bağımsızdır'], 'Aşırı yükte akım uzun süre yüksek kalınca bimetal ısınıp bükülerek devreyi açar. Kısa devrede ani büyük akım elektromıknatısı çalıştırır ve devre anında kesilir.'),
  ('100 Ω\'luk (1/4 W) ve 400 Ω\'luk (1/4 W) iki direnç seri bağlanıyor. Direncin güç sınırı aşılmadan bileşime en fazla kaç volt uygulanabilir?', '12,5 V', ['25 V', '5 V', '10 V'], '100 Ω için sınır akım 50 mA, 400 Ω için 25 mA\'dir. Seri devrede küçük olanı geçemeyiz: I = 25 mA ve V = 0,025 × 500 = 12,5 V\'tur.'),
  ('Karanlıkta 100 kΩ, aydınlıkta 1 kΩ direnç gösteren bir LDR, 5 V\'a bağlı gerilim bölücüde üst dirençtir; alt direnç 10 kΩ\'dur. Karanlıkta alt direncin uçlarındaki çıkış gerilimi yaklaşık kaç volttur?', '0,45 V', ['4,55 V', '2,5 V', '5 V'], 'Karanlıkta toplam direnç 110 kΩ\'dur. Çıkış gerilimi V = 5 × 10/110 ≈ 0,45 V olur; aydınlıkta ise yaklaşık 4,55 V olur.'),
  ('Bir küpün kenarları, her biri R direncinde ince tellerden yapılmıştır. Küpün aynı yüzündeki iki karşıt köşe devreye bağlanırsa uçlar arasındaki eşdeğer direnç kaç R olur?', '3R/4', ['5R/6', '7R/12', 'R/2'], 'Simetri ve eşpotansiyel noktaların birleştirilmesiyle yüz köşegeni arasındaki eşdeğer direnç 3R/4 bulunur.'),
  ('Bir köprü devresinde kollar 2 Ω–4 Ω ve 3 Ω–6 Ω\'dur (2/4 = 3/6); köprü kolunda ayrıca 10 Ω\'luk bir direnç vardır. A–B uçları arasındaki eşdeğer direnç kaç ohmdur?', '3,6 Ω', ['6 Ω', '4,5 Ω', '7,5 Ω'], 'Köprü dengelidir; 10 Ω\'dan akım geçmez. (2+4) Ω ile (3+6) Ω paralel: (6·9)/15 = 3,6 Ω olur.'),
  ('Emk\'sı 12 V ve iç direnci 0,5 Ω olan bir akü, ters yönden 4 A akımla şarj ediliyor. Şarj sırasında akünün uçları arasındaki gerilim kaç volttur?', '14 V', ['10 V', '12 V', '16 V'], 'Şarj sırasında akım pilin içinden artı uca doğru girer; uç gerilimi V = ε + I·r = 12 + 4 × 0,5 = 14 V olur.'),
  ('12 V emk\'lı, 0,5 Ω iç dirençli bir akü 4 A akımla şarj ediliyor. Akünün iç direncinde ısıya dönüşen güç kaç watttır?', '8 W', ['2 W', '48 W', '56 W'], 'İç dirençteki güç P = I²r = 16 × 0,5 = 8 W\'tır; bu güç şarj sırasında kaybolur.'),
  ('Elektrik tesisatında ani yüksek gerilim darbelerinden (yıldırım düşmesi, şebeke anahtarlaması) cihazları korumak için kullanılan ve gerilim yükselince direnci hızla düşen eleman hangisidir?', 'Varistör', ['Potansiyometre', 'LDR', 'Elektrolitik kondansatör'], 'Varistör, eşik üstü gerilimde direnci keskin biçimde azalan bir elemandır; aşırı gerilim darbelerini üzerinden geçirip cihazı korur.'),
  ('Seri bir devrede lambanın teli kopmuş ve devre açılmıştır. Kopuk lambanın uçlarına doğrudan bir ampermetre bağlamak neden uygun değildir?', 'Ampermetrenin çok küçük direnci devreyi kapatır ve akım yalnızca öteki elemanlarca sınırlanır, aşırı akım doğabilir', ['Ampermetre kopuk lambanın gerilimini ölçemediği için aletin ibresi hiç sapmaz ve alet bozulur', 'Ampermetre gerilimi sıfırladığı için kaynak kendiliğinden kısa devre olur ve lamba onarılır', 'Ampermetre yalnızca doğru akımda çalıştığından alternatif akım devresinde her zaman bozulur'], 'İdeal ampermetre çok küçük dirençlidir; kopuk lambanın uçlarına bağlanınca devre tamamlanır ve akım lambanın direnci olmadan yalnızca diğer elemanlarla sınırlanır. Devre aşırı akım çekebilir ve alet zarar görebilir.'),
  ('Bir iletkenin kesitinden geçen yük q = 3t² (q coulomb, t saniye) bağıntısıyla artmaktadır. t = 2 s anındaki anlık akım şiddeti kaç amperdir?', '12 A', ['6 A', '4,5 A', '24 A'], 'Akım, yükün zamana göre türevidir: I = dq/dt = 6t. t = 2 s için I = 12 A bulunur.'),
  ('Direnci 20 Ω olan düzgün bir tel uzunluğunun 1/3\'ü ve 2/3\'ü olacak biçimde ikiye kesiliyor ve iki parça paralel bağlanıyor. Eşdeğer direnç kaç ohmdur?', '40/9 Ω ≈ 4,44 Ω', ['20 Ω', '6,67 Ω', '10 Ω'], 'Parçaların dirençleri 20/3 Ω ve 40/3 Ω\'dur. Paralel eşdeğeri (20/3·40/3)/(20) = 40/9 Ω\'dur.'),
  ('Aynı kesitte ve aynı akımı taşıyan bir metal tel ile bir yarı iletken çubuk karşılaştırılıyor. Yarı iletkende serbest yük taşıyıcı yoğunluğu metale göre çok küçüktür. Sürüklenme hızı için ne söylenebilir?', 'Yarı iletkende çok daha büyüktür', ['Yarı iletkende çok daha küçüktür, çünkü akım daha az taşıyıcıyla taşınır', 'Her ikisinde de aynıdır', 'Yarı iletkende sıfırdır'], 'v = I/(nAe) olduğundan taşıyıcı yoğunluğu n çok küçük olunca aynı akımı taşımak için taşıyıcıların daha hızlı sürüklenmesi gerekir.'),
  ('220 V için 25 W, 60 W ve 100 W yazan üç lamba önce seri, sonra paralel bağlanıp 220 V\'a takılıyor. Seri ve paralel bağlamada en parlak yanan lambalar sırasıyla hangileridir?', '25 W\'lık, 100 W\'lık', ['100 W\'lık, 25 W\'lık', '25 W\'lık, 25 W\'lık', '100 W\'lık, 100 W\'lık'], 'Seri bağlamada akım ortak olduğundan P = I²R\'nin büyük olduğu, yani direnci en büyük olan 25 W\'lık lamba parlaktır. Paralelde gerilim ortaktır ve P = V²/R en büyük olan 100 W\'lık lambadadır.'),
  ('5 V\'luk kaynağa seri bağlı 2 kΩ ve 3 kΩ\'luk dirençlerden oluşan gerilim bölücünün çıkışına (3 kΩ\'un uçlarına) 3 kΩ\'luk bir yük bağlanıyor. Çıkış gerilimi yaklaşık kaç volt olur?', '2,14 V', ['3 V', '2,5 V', '1,5 V'], '3 kΩ ile yük paralel olunca 1,5 kΩ eder. Çıkış gerilimi 5 × 1,5/(2 + 1,5) ≈ 2,14 V\'a düşer; yükleme etkisi bölücünün çıkışını azaltır.'),
  ('Potansiyometre yönteminin, emk ölçümünde voltmetreye göre en büyük avantajı nedir?', 'Denge anında ölçülen pilden akım çekilmediği için iç direnç etkisi olmaz', ['Pilin emk\'sını artırması', 'Ölçümde ampermetreye gerek duyulmaması', 'Piller yerine kondansatör kullanması'], 'Denge durumunda galvanometreden akım geçmez ve ölçülen pil yük çekmez; böylece uç gerilimi gerçek emk\'ya eşit okunur.'),
  ('İletkenliği σ = 5,8 × 10⁷ S/m olan bakır telde elektrik alan 0,1 V/m ise akım yoğunluğu kaç A/m²\'dir?', '5,8 × 10⁶ A/m²', ['5,8 × 10⁸ A/m²', '5,8 × 10⁹ A/m²', '1,7 × 10⁻⁹ A/m²'], 'Ohm yasasının mikroskobik biçimi J = σE\'dir: 5,8×10⁷ × 0,1 = 5,8×10⁶ A/m².'),
  ('12 V\'luk ideal bir kaynağın artı ucu T, eksi ucu B noktasıdır. T–L arasında 2 Ω, L–B arasında 6 Ω, T–R arasında 4 Ω, R–B arasında 4 Ω ve L–R arasında 2 Ω\'luk dirençler vardır. L–R köprü direncinden geçen akım yaklaşık kaç amperdir?', '0,55 A', ['0,055 A', '1,5 A', '3,14 A'], 'Düğüm gerilimleri V_L ≈ 8,18 V ve V_R ≈ 7,09 V bulunur. Köprü akımı (8,18 − 7,09)/2 = 6/11 ≈ 0,55 A\'dir ve L\'den R\'ye doğrudur.'),
  ('12 V\'luk ideal kaynağa 2 kΩ\'luk bir direnç, 4 kΩ\'luk ikinci bir dirençle seri bağlıdır ve 5 μF\'lık bir kondansatör 4 kΩ\'luk direncin uçlarına paralel bağlanmıştır. Uzun süre sonra kondansatörde biriken yük kaç μC olur?', '40 μC', ['60 μC', '20 μC', '30 μC'], 'Kararlı durumda kondansatörden akım geçmez. Devre 2 kΩ ve 4 kΩ\'dan oluşan bir bölücüdür; 4 kΩ\'un gerilimi 8 V\'tur. q = CV = 5 × 8 = 40 μC.'),
  ('Emk\'sı 12 V ve iç direnci 1 Ω olan bir üretece, her biri 5 Ω olan özdeş lambalar bağlanıyor. Tek lamba bağlıyken lamba 20 W güç harcarken ikinci özdeş lamba paralel eklenirse ilk lambanın gücü yaklaşık yüzde kaç azalır?', '%26', ['%50', '%10', '%75'], 'Tek lambada I = 12/6 = 2 A, P = 20 W. İki lambada R = 2,5 Ω; I = 12/3,5 ≈ 3,43 A ve lamba gerilimi ≈ 8,57 V olur; P = 8,57²/5 ≈ 14,7 W. Azalma (20 − 14,7)/20 ≈ %26\'dır.'),
  ('Her biri 1,5 V emk\'lı ve 0,5 Ω iç dirençli 12 özdeş pil, 1,5 Ω\'luk bir dirence en büyük akımı verecek biçimde düzenlenecektir. Hangi düzenleme ve akım doğrudur?', '6 seri × 2 paralel; yaklaşık 3 A', ['12 seri; yaklaşık 2,4 A', '4 seri × 3 paralel; yaklaşık 2,77 A', '2 seri × 6 paralel; yaklaşık 1,8 A'], 'Dizi eşdeğeri (6 seri × 2 paralel) 9 V ve 1,5 Ω\'dur; dış direnç iç dirence eşit olduğundan akım 9/3 = 3 A ve diğer düzenlemelerden büyüktür.'),
  ('220 V\'ta sırasıyla 400 W ve 600 W güç veren iki rezistans birbirine seri bağlanıp 220 V\'a bağlanırsa toplam güç kaç watt olur?', '240 W', ['1000 W', '500 W', '100 W'], 'Dirençler R₁ = 220²/400 ve R₂ = 220²/600\'dür. Seri güç, P = V²/(R₁ + R₂) = 1/(1/400 + 1/600) = 240 W\'tır.'),
  ('220 V için 40 W ve 60 W yazan iki lamba birbirine seri bağlanıp 220 V\'a bağlanırsa 40 W\'lık lambanın harcadığı güç yaklaşık kaç watt olur?', '14,4 W', ['40 W', '24 W', '9,6 W'], 'Dirençler 1210 Ω ve 806,7 Ω\'dur. Akım 220/2016,7 ≈ 0,109 A; 40 W\'lık lambada P = I²R ≈ 14,4 W\'tır (60 W\'lıda ≈ 9,6 W).'),
  ('Emk\'sı 12 V ve 6 V olan iki ideal pil sırasıyla 2 Ω ve 1 Ω\'luk dirençlerle ayrı kollarda bağlıdır; kollar bir yanda doğrudan birleşir ve diğer yanda ortak 2 Ω\'luk bir yük direncine bağlanır. 6 V\'luk pilden geçen akım kaç amperdir?', '0 A', ['3 A', '1,5 A', '6 A'], 'Düğüm gerilimi V ise (12−V)/2 + (6−V)/1 = V/2 olur; V = 6 V bulunur. 6 V\'luk koldaki gerilim farkı sıfırdır; bu koldan akım geçmez.'),
  ('Tam ölçek akımı 1 mA ve tam ölçekteki gerilimi 50 mV olan bir galvanometre 0–5 V\'luk voltmetreye dönüştürülecektir. Seri bağlanacak çarpan direnç kaç ohm olmalıdır?', '4950 Ω', ['5000 Ω', '4900 Ω', '49 950 Ω'], 'Galvanometrenin iç direnci 50 mV / 1 mA = 50 Ω\'dur. Toplam direnç 5/0,001 = 5000 Ω olmalıdır; çarpan direnç 5000 − 50 = 4950 Ω\'dur.'),
  ('Direnci 48,4 Ω olan bir ısıtıcı, 220 V\'luk şebekeye toplam direnci 0,5 Ω olan bir kabloyla bağlanıyor. Isıtıcının gerçekte harcadığı güç yaklaşık kaç watttır? (Şebeke gerilimi 220 V kabul ediliyor)', '980 W', ['1000 W', '950 W', '1020 W'], 'Toplam direnç 48,9 Ω, akım ≈ 4,50 A\'dir. Isıtıcıda P = I²R ≈ 20,2 × 48,4 ≈ 980 W olur; kablo yaklaşık 10 W kaybettirir.'),
  ('Başlangıçta boş olan bir kondansatör, zaman sabiti 2 s olan bir RC devresiyle 12 V\'luk bir kaynaktan dolduruluyor. Anahtar kapatıldıktan 4 saniye sonra kondansatörün gerilimi yaklaşık kaç volt olur? (e⁻² ≈ 0,135)', '10,4 V', ['8 V', '6 V', '12 V'], 'Dolma sırasında V = ε(1 − e^(−t/τ)) olduğundan t = 2τ için V ≈ 12 × (1 − 0,135) ≈ 10,4 V olur.'),
  ('Emk\'ları 9 V ve 3 V olan iki ideal pil, toplam direnci 6 Ω olan bir ilmekte zıt yönde bağlıdır. Bu devrede 3 V\'luk pilin aldığı (şarj olurken yuttuğu) güç kaç watttır?', '3 W', ['9 W', '18 W', '1 W'], 'Net emk 6 V, I = 1 A\'dir. Akım 3 V\'luk pile ters yönden girer ve bu pil P = εI = 3 × 1 = 3 W güç yutar; 9 V\'luk pil 9 W verir.'),
  ('Gücü 6 kW olan bir elektrikli şofben (verim %100) dakikada yaklaşık kaç litre suyu 15 °C\'den 45 °C\'ye ısıtabilir? (c = 4200 J/kg·°C, 1 L su = 1 kg)', '2,9 litre', ['0,05 litre', '29 litre', '8,6 litre'], 'Birim zamanda ısıtılan kütle m/t = P/(cΔT) = 6000/(4200 × 30) ≈ 0,048 kg/s\'dir; bu da dakikada yaklaşık 2,9 kg yani 2,9 L eder.'),
  ('Direnci 0,5 Ω olan bir bakır telden 100 saniye boyunca 10 A akım geçiyor. Isı kaybı yoksa kütlesi 0,1 kg olan telin sıcaklığı yaklaşık kaç °C artar? (c = 390 J/kg·°C)', '128 °C', ['13 °C', '1280 °C', '50 °C'], 'Açığa çıkan ısı Q = I²Rt = 100 × 0,5 × 100 = 5000 J\'dür. ΔT = Q/(mc) = 5000/(0,1 × 390) ≈ 128 °C\'dir.'),
  ('1986–1987 yıllarında keşfedilen \'yüksek sıcaklık süper iletkenleri\' kimi alanlarda neden büyük önem taşımıştır?', 'Sıvı azot sıcaklığında da süper iletken olup soğutma maliyetini düşürmeleri', ['Oda sıcaklığında hiç direnç göstermedikleri ve soğutma gerektirmedikleri için', 'Sıvı helyum gerektirmeleri ve daha pahalı olmaları', 'Yalnızca mutlak sıfırda iletken olmaları'], 'Bakır oksit seramikleri gibi malzemeler sıvı azot sıcaklığının (77 K) üzerinde süper iletken olur; soğutma sıvı helyuma göre çok daha ucuzdur. Oda sıcaklığında süper iletkenlik ise keşfedilmiş değildir.'),
  ('Bir LED lamba 40 lira, ona eşdeğer akkor lamba 5 lira tutmaktadır. LED 10 W, akkor lamba 60 W çekmektedir. Günde 4 saat kullanımda ve 1 kWh = 2 lira varsayımıyla LED lambanın fiyat farkını çıkarma süresi yaklaşık ne kadardır?', 'Yaklaşık 3 ay', ['Yaklaşık 3 yıl', 'Yaklaşık 3 gün', 'Yaklaşık 10 yıl'], 'Yıllık enerji farkı 0,05 kW × 4 h × 365 ≈ 73 kWh = 146 liradır. Fiyat farkı 35 lira olduğundan geri ödeme yaklaşık 35/146 yıl ≈ 87 gün, yani yaklaşık 3 aydır.'),
  ('12 V ve 100 Ah\'lik bir akü, verimi %85 olan bir evirici (inverter) üzerinden 1000 W\'lık bir cihazı yaklaşık kaç saat çalıştırabilir? (Akünün tamamı kullanılabilir kabul edilsin)', 'Yaklaşık 1 saat', ['Yaklaşık 12 saat', 'Yaklaşık 0,1 saat', 'Yaklaşık 10 saat'], 'Akünün enerjisi 12 × 100 = 1200 Wh\'tır. Evirici kaybıyla kullanılabilir enerji 1020 Wh\'tir; süre 1020/1000 ≈ 1,02 saattir.'),
  ('Aynı işi gören iki elektrik motorundan A\'nın verimi %60, B\'nin verimi %80\'dir. Her ikisi de 1 saatte 2 kWh yararlı iş yapacaksa şebekeden çekilen elektrik enerjileri farkı yaklaşık kaç kWh olur?', 'Yaklaşık 0,83 kWh (A daha çok)', ['0,4 kWh (B daha çok)', '2 kWh (A daha çok)', '0,2 kWh (A daha çok)'], 'A için 2/0,6 ≈ 3,33 kWh, B için 2/0,8 = 2,5 kWh çekilir. Fark yaklaşık 0,83 kWh\'tir ve A daha çok enerji harcar.'),
  ('Üç özdeş 9 Ω\'luk direnç üçgen (Δ) biçiminde bağlanmıştır. Aynı uçlar arasında eşdeğer davranan yıldız (Y) bağlantısında her kolun direnci kaç ohm olmalıdır?', '3 Ω', ['27 Ω', '9 Ω', '6 Ω'], 'Özdeş dirençler için Δ–Y dönüşümünde R_Y = R_Δ/3\'tür. 9/3 = 3 Ω bulunur.'),
  ('A uçundan başlayarak sırasıyla 6 Ω seri, X düğümünde B\'ye 6 Ω\'luk paralel kol, 6 Ω seri, Y düğümünde B\'ye 6 Ω\'luk paralel kol bulunan iki basamaklı bir merdiven devresinin A–B uçları arasındaki eşdeğer direnç kaç ohmdur?', '10 Ω', ['12 Ω', '8 Ω', '18 Ω'], 'Sondan başlanır: Y\'deki paralel 6 Ω ile önceki seri 6 Ω birleşince 12 Ω olur. X düğümünde 6 Ω ile 12 Ω paralel: 4 Ω. Başlangıçtaki seri 6 Ω ile 6 + 4 = 10 Ω bulunur.'),
  ('Emk\'sı 12 V ve iç direnci 1 Ω olan bir üretece 3 Ω\'luk sabit bir direnç ile ayarlanabilir bir R direnci seri bağlanmıştır. Ayarlanabilir R\'de harcanan güç en büyük olması için R kaç ohm olmalıdır?', '4 Ω', ['1 Ω', '3 Ω', '8 Ω'], 'R\'nin gördüğü kaynak, emk\'sı 12 V ve iç direnci 3 + 1 = 4 Ω olan bir kaynak gibidir. Güç, R bu eşdeğer iç dirence eşit olduğunda en büyüktür: R = 4 Ω.'),
  ('12 V\'luk kaynağa 690 Ω\'luk bir direnç seri bağlıdır ve bu dirençten sonra paralel olarak 5,1 V\'luk bir zener diyot ile 1 kΩ\'luk bir yük direnci bağlanmıştır. Zener diyot ters yönde iletim bölgesindedir. Zener diyottan geçen akım kaç miliamperdir?', '4,9 mA', ['10 mA', '5,1 mA', '15,1 mA'], 'Seri dirençten geçen toplam akım (12 − 5,1)/690 = 10 mA\'dir. Yük akımı 5,1/1000 = 5,1 mA olduğundan zenerden 10 − 5,1 = 4,9 mA geçer.'),
  ('Paralel levhalı bir kondansatörün levha alanının yarısı, levhalar arasını tamamen dolduran dielektrik sabiti 3 olan bir yalıtkanla doldurulmuştur; diğer yarı boştur. Sığa, boş kondansatörün sığası C₀\'ın kaç katı olur?', '2 katı', ['3 katı', '1,5 katı', '4 katı'], 'Alanın iki yarısı birbirine paralel iki kondansatör gibidir: C = (C₀/2)·3 + (C₀/2)·1 = 2C₀\'dır.'),
  ('Paralel levhalı bir kondansatörün levhaları arasındaki mesafenin yarısı, levha alanını tamamen kaplayan dielektrik sabiti 3 olan bir yalıtkanla dolduruluyor; diğer yarı boştur. Sığa, boş kondansatörün sığası C₀\'ın kaç katı olur?', '1,5 katı', ['2 katı', '3 katı', '0,75 katı'], 'Kalınlığın iki yarısı seri iki kondansatör gibidir: 1/C = 1/(6C₀) + 1/(2C₀) = 4/(6C₀) olduğundan C = 1,5C₀\'dır.'),
  ('12 V\'a yüklenmiş 4 μF\'lık kondansatör, kaynaktan ayrıldıktan sonra 6 V\'a yüklenmiş 2 μF\'lık başka bir kondansatörün uçlarına ters kutuplar birleşecek biçimde (artı levha eksi levhaya) bağlanıyor. Ortak gerilim kaç volt olur?', '6 V', ['10 V', '9 V', '3 V'], 'Yükler 48 μC ve 12 μC\'dur; ters kutuplu bağlamada net yük 48 − 12 = 36 μC kalır. Ortak gerilim V = 36/(4+2) = 6 V\'tur.'),
  ('CuSO₄ çözeltisinden 2 A\'lik akım 965 saniye geçirilirse katotta yaklaşık kaç gram bakır toplanır? (Cu: 63,5 g/mol, bakır iyonu Cu²⁺, 1 mol elektronun yükü 96 500 C)', '0,635 g', ['1,27 g', '0,0635 g', '6,35 g'], 'Geçen yük 2 × 965 = 1930 C\'dur; bu 0,02 mol elektrona karşılık gelir. Cu²⁺ için 0,01 mol Cu, yani 0,635 g toplanır.'),
  ('12 V ve 2 Ω seri dirençli bir koldan; 6 V ve 1 Ω seri dirençli ikinci koldan beslenen ortak bir düğümden toprağa bağlı 6 Ω\'luk yük bulunmaktadır (iki kaynak aynı yönde). Yükten geçen akım kaç amperdir?', '1,2 A', ['2 A', '3 A', '0,12 A'], 'Düğüm gerilimi V ise (12−V)/2 + (6−V)/1 = V/6 olur; V = 7,2 V bulunur. Yük akımı 7,2/6 = 1,2 A\'dir (6 V\'luk pil bu durumda şarj olur).'),
  ('Emk\'sı 15 V ve iç direnci 1 Ω olan bir üretecin dış devresinde birbirine paralel 4 Ω ve 12 Ω\'luk dirençler bulunmaktadır. 12 Ω\'luk dirençten geçen akım kaç amperdir?', '0,9375 A', ['3,75 A', '1,25 A', '0,09375 A'], 'Paralel grup 3 Ω, toplam direnç 4 Ω\'dur ve I = 15/4 = 3,75 A olur. Uç gerilimi 15 − 3,75 × 1 = 11,25 V; 12 Ω\'dan 11,25/12 = 0,9375 A geçer.'),
  ('Bir üretecin uç gerilimi–akım doğrusu V eksenini 9 V\'ta, I eksenini 3 A\'de kesmektedir. Bu üretecin dış devreye aktarabileceği en büyük güç kaç watttır?', '6,75 W', ['27 W', '13,5 W', '10,125 W'], 'Doğrunun kestiği noktalar ε = 9 V ve kısa devre akımı 3 A\'dir; r = 3 Ω olur. En büyük güç P = ε²/4r = 81/12 = 6,75 W\'tır.'),
  ('Emk\'sı ε, iç direnci r olan bir üretecin dış devreye verdiği güç P = εI − I²r ifadesiyle verilir. Dış güç hangi akım değerinde en büyüktür?', 'ε/(2r)', ['ε/r', '2ε/r', 'ε²/(4r)'], 'P(I) parabolünün tepe noktası dP/dI = ε − 2Ir = 0 koşuluyla I = ε/(2r)\'de bulunur; bu akımda dış direnç iç dirence eşittir.'),
  ('Emk\'ları 12 V olan iki pilden birinin iç direnci 1 Ω, diğerinin 2 Ω\'dur. Piller paralel bağlanıp ortak uçlarına 2 Ω\'luk dış direnç bağlanırsa 1 Ω iç dirençli pilden geçen akım kaç amperdir?', '3 A', ['6 A', '4,5 A', '1,5 A'], 'Düğüm gerilimi V = (12/1 + 12/2)/(1 + 1/2 + 1/2) = 9 V\'tur. 1 Ω iç dirençli pilden (12 − 9)/1 = 3 A geçer; diğerinden 1,5 A, dış dirençten 4,5 A geçer.'),
  ('Yeşil, mavi, altın ve altın bantlı dört bantlı bir direncin değeri nedir? (Yeşil 5, mavi 6; üçüncü bant altın çarpanı 0,1; dördüncü bant ±%5)', '5,6 Ω, ±%5', ['56 Ω, ±%5', '560 Ω, ±%5', '5,6 kΩ, ±%10'], 'İlk iki bant 5 ve 6\'dır (56); altın çarpanı ×0,1 verir. Değer 5,6 Ω, tolerans ±%5\'tir.'),
  ('Bir metalde çarpışmalar arasındaki ortalama süre τ = 2 × 10⁻¹⁴ s, elektrik alan 0,1 V/m\'dir. Sürüklenme hızı v = eEτ/m bağıntısıyla yaklaşık kaç m/s\'dir? (e = 1,6 × 10⁻¹⁹ C, m = 9,1 × 10⁻³¹ kg)', '3,5 × 10⁻⁴ m/s', ['3,5 × 10⁻⁷ m/s', '3,5 × 10⁵ m/s', '3,5 × 10⁻¹ m/s'], 'v = (1,6×10⁻¹⁹ × 0,1 × 2×10⁻¹⁴) / (9,1×10⁻³¹) ≈ 3,5×10⁻⁴ m/s\'dir; bu değer gerçekten milimetrenin altında bir hızdır.'),
  ('Drude modeline göre bir metalde elektronların çarpışmalar arasındaki ortalama süresi τ artarsa (diğer nicelikler sabit) iletkenin özdirenci nasıl değişir?', 'Azalır', ['Artar', 'Değişmez', 'Önce artar sonra sıfır olur'], 'Özdirenç ρ = m/(ne²τ) olduğundan τ büyüdükçe ρ küçülür; çarpışmalar daha seyrek olduğunda elektronlar daha uzun süre ivmelenir.'),
  ('Zaman sabiti τ = 10 s olan bir RC devresinde dolu bir kondansatör boşalıyor. Kondansatör geriliminin ilk değerinin yarısına inmesi için gereken süre yaklaşık kaç saniyedir? (ln 2 ≈ 0,693)', '6,93 s', ['5 s', '10 s', '3,47 s'], 'V = V₀e^(−t/τ) = V₀/2 için t = τ ln 2 = 10 × 0,693 ≈ 6,93 s\'dir.'),
  ('Zaman sabiti τ = 10 s olan RC devresinde boşalan kondansatörün enerjisinin ilk değerinin yarısına inmesi yaklaşık kaç saniye sürer? (ln 2 ≈ 0,693)', '3,47 s', ['6,93 s', '5 s', '1,39 s'], 'Enerji gerilimin karesiyle orantılıdır ve U = U₀e^(−2t/τ)\'dir. U = U₀/2 için t = (τ/2) ln 2 ≈ 3,47 s olur.'),
  ('Bir dirençte gerilim 6,0 ± 0,1 V ve akım 0,30 ± 0,01 A ölçülmüştür. Direnç değeri ve yaklaşık mutlak belirsizliği nedir?', '20 Ω; yaklaşık ± 1 Ω', ['20 Ω; yaklaşık ± 0,1 Ω', '18 Ω; yaklaşık ± 5 Ω', '20 Ω; yaklaşık ± 10 Ω'], 'R = V/I = 20 Ω\'dur. Bağıl belirsizlikler yaklaşık %1,7 ve %3,3\'tür; toplamı yaklaşık %5 yapar ve ±1 Ω\'a karşılık gelir.'),
  ('12 V\'luk kaynağa 690 Ω\'luk seri direnç ve 5,1 V\'luk zener diyot (ters yönde) bağlanmıştır. Yük zenerle paralel bağlanırsa, zener akımı sıfıra inmeden yükün çekebileceği en büyük akım yaklaşık kaç miliamperdir?', '10 mA', ['5,1 mA', '6,9 mA', '15,1 mA'], 'Seri dirençten geçen toplam akım (12 − 5,1)/690 = 10 mA\'dir. Yük bu akımın tamamını çekerse zener akımı sıfıra iner; bu, regülasyonun sınırıdır.'),
  ('1000 MW\'lık güç 400 kV\'luk bir hatla iletiliyor ve hattın toplam direnci 10 Ω\'dur. Hat kaybı iletilen gücün yüzde kaçı eder?', '%6,25', ['%0,625', '%62,5', '%2,5'], 'Akım 2500 A\'dir. Kayıp I²R = 2500² × 10 = 62,5 MW\'tır; bu da 62,5/1000 = %6,25\'tir.'),
  ('Özdeş üç lambadan biri, birbirine paralel iki lambayla seri bağlanıp bir kaynağa takılmıştır. Tek bir lambanın aynı kaynağa doğrudan bağlanmasıyla harcayacağı güç P₀ ise bu düzenin toplam gücü kaç P₀\'dır?', '2P₀/3', ['3P₀/2', '4P₀/9', '3P₀'], 'Düzenin eşdeğer direnci 1,5R\'dir. Aynı gerilimde güç dirençle ters orantılı olduğundan P = P₀/1,5 = 2P₀/3 olur.'),
  ('Bir üreteçte dış direnç R = 4r iken dış devreye aktarılan güç, R = r iken aktarılan en büyük gücün yüzde kaçıdır?', '%64', ['%100', '%80', '%25'], 'P(R) = ε²R/(R+r)² olduğundan R = 4r için P = 4ε²/(25r), R = r için P_max = ε²/(4r)\'dir. Oran 16/25 = 0,64 yani %64\'tür.'),
  ('Her kenarı R olan kare tel çerçevenin bir köşegeni de R direncinde bir telle bağlanmıştır. Köşegenin iki ucu arasındaki eşdeğer direnç kaç R\'dir?', 'R/2', ['R', '2R/3', '3R/4'], 'Köşegen uçları arasında üç yol paraleldir: köşegen (R) ve iki ikili kenar (2R, 2R). 1/R_eş = 1/R + 1/2R + 1/2R = 2/R olduğundan R_eş = R/2\'dir.'),
  ('12 kenarının her birinin direnci R olan küp iskeletinde komşu iki köşe (aynı kenarın uçları) arasındaki eşdeğer direnç kaç R\'dir?', '7R/12', ['5R/6', '3R/4', '11R/12'], 'Simetri analiziyle komşu köşeler arasındaki eşdeğer direnç 7R/12 bulunur; bu değer cisim köşegeni (5R/6) ve yüz köşegeni (3R/4) değerlerinden farklıdır.'),
];
